import React from 'react';
import { useAdvancedTheme } from '../context/AdvancedThemeContext';

const AdvancedThemeControls = () => {
  const { mode, colors, isDark, toggleTheme, setPrimaryColor, resetTheme } = useAdvancedTheme();
  
  const colorPresets = ['#007bff', '#28a745', '#dc3545', '#ffc107', '#6f42c1'];

  return (
    <div style={{ background: colors.surface, padding: '1.5rem', borderRadius: '8px', border: `1px solid ${colors.border}`, margin: '1rem 0' }}>
      <h3 style={{ color: colors.primary, marginTop: 0 }}>Advanced Theme Controls</h3>
      
      <div style={{ marginBottom: '1rem' }}>
        <p><strong>Mode:</strong> {mode.toUpperCase()}</p>
        <button onClick={toggleTheme} style={{ padding: '0.5rem 1rem', cursor: 'pointer', background: colors.primary, color: '#fff', border: 'none', borderRadius: '4px' }}>
          {isDark ? 'Switch to Light' : 'Switch to Dark'}
        </button>
      </div>

      <div style={{ marginBottom: '1rem' }}>
        <p><strong>Primary Color:</strong></p>
        <div style={{ display: 'flex', gap: '0.5rem' }}>
          {colorPresets.map(color => (
            <button 
              key={color} 
              onClick={() => setPrimaryColor(color)}
              style={{ width: '30px', height: '30px', background: color, border: 'none', borderRadius: '4px', cursor: 'pointer' }} 
            />
          ))}
        </div>
      </div>

      <button onClick={resetTheme} style={{ padding: '0.5rem 1rem', cursor: 'pointer', background: '#dc3545', color: '#fff', border: 'none', borderRadius: '4px' }}>
        Reset Theme
      </button>
    </div>
  );
};

export default AdvancedThemeControls;
